css:
.header {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    border-bottom: 1px solid #dddddd;
    padding-bottom: 4px;
}

.info {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    border-bottom: 1px solid #dddddd;
    padding-bottom: 2px;

}

.grayscale { filter: grayscale(100%); }

html:
{% set company = frappe.db.get_value("Company", doc.company, ["*"], as_dict = true) %}
{% set letter_head = frappe.db.get_value("Letter Head", company.default_letter_head, ["image"], as_dict=true) %}
{% set links = frappe.get_all('Dynamic Link', filters={'link_doctype': 'Company', 'link_name': doc.company, 'parenttype': 'Address'}, fields=['parent']) %}
{% set address = None %}
{% if links %}
{% set address = frappe.db.get_value("Address", links[0].parent, ["*"], as_dict=true) %}
{% endif %}

{% set patient = frappe.db.get_value("Patient", doc.patient, ["*"], as_dict=true) %}
{% set practitioner = frappe.db.get_value("Healthcare Practitioner", doc.practitioner, ["*"], as_dict=true) %}
{% set dob = frappe.utils.getdate(patient.dob) %}
{% set today = frappe.utils.nowdate() %}
{% set birth_date = frappe.utils.getdate(dob) %}
{% set current_date = frappe.utils.getdate(today) %}
{% set age = current_date.year - birth_date.year - ((current_date.month, current_date.day) < (birth_date.month, birth_date.day)) %}
{% set treatments = json.loads(doc.treatment) if doc.treatment else [] %}

{% macro header() %}
<div class="header">
    <div>
        <img src="{{ letter_head.image }}" style="width:100px; margin-bottom:32px;" class="grayscale" />

    </div>

    <div style="text-align: right;">
        {#{% if address.address_title %}#}
            {#<p style="font-weight: bold; font-size: large;">{{address.address_title}}<p/>#}
        {#{% endif %}#}
        <p style="font-weight: bold; font-size: large;"> {{ doc.company }} </p>
        {% if address.address_line1 %}
            <p>{{address.address_line1}}</p>
        {% endif %}
        {% if address.city %}
            <p>{{address.city}}</p>
        {% endif %}
        {% if address.pincode %}
            <p>{{address.pincode}}</p>
        {% endif %}
        <p style="margin: 0;">Tel: 4908128</p>
        {#<p>BRN: C22188669</p>#}
        <p><strong>Date:</strong> {{ frappe.utils.formatdate(doc.creation, "dd MMMM yyyy") }}</p>
    </div>
</div>
{% endmacro %}



{% macro practitioner_patient_info() %}
<h2 style="text-align: center;">Consultation Report</h2>
<div style="border: 2px solid #4a4a4a; background-color: #f0f0f0; padding: 16px; margin-top: 36px; margin-bottom: 20px; display: flex; justify-content: space-between; border-radius: 8px;">
    <div style="flex: 1; text-align: left;">
        <div>
            <strong>Patient:</strong><br/>
            {{ patient.patient_name }}, {{ age }}, {{ patient.sex[0] }}<br/>
            {{ patient.uid }}<br/>
            {{ patient.mobile }}
        </div>
    </div>

    <div style="flex: 1; border:1px;">
        <p></p>
    </div>
     <div style="flex: 1; border:1px;">
        <p></p>
    </div>


    <div style="flex: 1;">
        <div style="margin-bottom: 8px;">
            <strong>Practitioner:</strong><br/>
            {{ practitioner.practitioner_name }}
        </div>
        <div>
            <strong>Speciality:</strong><br/>
            {{ practitioner.speciality }}
        </div>
    </div>
</div>
{% endmacro %}

{% macro footer() %}
<div class="info footer" style="text-align: center; margin-top: 40px; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 200px;">
    <div class="signature-section" style="display: flex; flex-direction: column; align-items: center; text-align: center; justify-content: center; height: 100%;">
        <h5 style="margin: 5px 0; font-size: 16px;">{{ practitioner.practitioner_name }}</h5>
        <h5 style="margin: 5px 0; font-size: 16px;">{{ practitioner.speciality }}</h5>
    </div>
</div>
{% endmacro %}


<div>
    {{header()}}
    {{practitioner_patient_info()}}

    <div style="font-size: 14px;">
    {% if doc.chief_complaint %}
    <h4>Chief Complaint</h4>
    <p>{{doc.chief_complaint}}</p>
    {% endif %}

    {% if doc.past_history %}
    <h4>Past History / Allergies</h4>
    <p>{{doc.past_history}}</p>
    {% endif %}

    {% if doc.clinical_examination %}
    <h4>Clinical Examination </h4>
    <p>{{doc.clinical_examination}}</p>
    {% endif %}

    {% if doc.investigation_done %}
    <h4>Investigation Done</h4>
    <p>{{doc.investigation_done}}</p>
    {% endif %}

    {% if doc.provisional_diagnosis %}
    <h4>Provisional Diagnosis</h4>
    <p>{{doc.provisional_diagnosis}}</p>
    {% endif %}

    {% if doc.plan %}
    <h4>Plan</h4>
    <p>{{doc.plan}}</p>
    {% endif %}

    {% if treatments and treatments|length > 0 %}
    <h4>Prescriptions</h4>
    <table class="table table-bordered table-auto border my-4" style="border-collapse: collapse; width: 100%;">
        <thead>
            <tr>
                <th style="border: 1px solid #ddd; padding: 8px; font-weight: bold;">Name</th>
                <th style="border: 1px solid #ddd; padding: 8px; font-weight: bold;">Qty</th>
                <th style="border: 1px solid #ddd; padding: 8px; font-weight: bold;">Route</th>
                <th style="border: 1px solid #ddd; padding: 8px; font-weight: bold;">Frequency</th>
                <th style="border: 1px solid #ddd; padding: 8px; font-weight: bold;">Period</th>
                <th style="border: 1px solid #ddd; padding: 8px; font-weight: bold;">Instructions</th>
            </tr>
        </thead>
        <tbody>
            {% for t in treatments %}
            <tr>
                <td style="border: 1px solid #ddd; padding: 8px;">{{t.name}}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">{{t.qty}}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">{{t.route}}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">{{t.frequency}}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">{% if t.period %}{{ t.period }}{% endif %}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">{{t.instructions}}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endif %}
    </div>

    {{ footer() }}

</div>
